run_query_body:
let mut c: u64 = 0;
let mut i: usize = t.n;
while i > 0
    invariant
        i <= t.n,
        valid_cols_t(t),
        c as int == count_c(t, i as int),
        c as int <= (t.n - i) as int,
    decreases i,
{
    i = i - 1;
    proof { lemma_count_c_step(t, i as int); }
    if t.a[i] > 100 {
        c = c + 1;
    }
}
let mut res: Vec<OutRow> = Vec::new();
res.push(OutRow { c: c });
res
